#!/bin/zsh
# Generated by kajo new: the native module of a Release build (AOT 2).
# With the project's KAJO_NATIVE = YES (the default), the release image's
# methods are generated as C by the checkout's prebuilt kajo, compiled by
# this Xcode's clang for the platform and architectures being built, and
# archived into .build/kajo/native/<key>/libkajo_native.a, <key> a hash
# of the image, kajo, the clang and the flags; the link takes it whole
# (KAJO_NATIVE_LDFLAGS_YES) and the app binds it at launch. A library
# whose stamp does not match its bytes is built again, never linked.
# Libraries of earlier images are removed: one library per platform
# stays. A step that fails stops the Release build with one line naming
# KAJO_NATIVE=NO, which builds the app interpreted.
# Debug, or KAJO_NATIVE = NO: nothing (the app runs interpreted).
# By hand: CONFIGURATION=Release scripts/build-native.sh
#   <platform> <archs> <target os version> [<target suffix>]
#   (macosx arm64 macos15.0, iphoneos arm64 ios18.0,
#   iphonesimulator arm64 ios18.0 -simulator)
set -euo pipefail
project=${0:A:h:h}
kajo_root='/path/to/kajo'
kajo=$kajo_root/Prebuilt/bin/kajo
platform=${1:-$PLATFORM_NAME}
archs=(${=${2:-$ARCHS}})
osver=${3:-$LLVM_TARGET_TRIPLE_OS_VERSION}
suffix=${4:-${LLVM_TARGET_TRIPLE_SUFFIX:-}}
cache=$project/.build/kajo
link=$cache/native/$platform/libkajo_native.a
if [[ ${CONFIGURATION:-} != Release || ${KAJO_NATIVE:-YES} != YES ]]; then
  rm -f $link ${link:h}/linked
  exit 0
fi
die() {
  print "error: the native module was not built: $1. Set KAJO_NATIVE=NO (in project.yml, or on the xcodebuild line) to build the app without it; it then runs interpreted."
  exit 1
}
[[ -x $kajo ]] || die "no prebuilt kajo at $kajo (is the Kajo checkout still there? Open the Kajo app once)"
"$project/scripts/build-images.sh" --image-only Release
img=$cache/app-release.img
aot=(--subset callees --cold-minsize --send-helper)
flags=(-O2)
cc=(xcrun --sdk $platform clang)
key=$( { shasum -a 256 $img $kajo | cut -d' ' -f1; $cc --version | head -1; print -- $aot $flags $platform $archs $osver $suffix } | shasum -a 256 | cut -c1-24)
dir=$cache/native/$key
lib=$dir/libkajo_native.a
if [[ ! -f $lib || ! -f $dir/stamp || $(cat $dir/stamp) != $(shasum -a 256 $lib | cut -d' ' -f1) ]]; then
  print "native module: generating and compiling ($platform $archs)"
  rm -rf $dir $dir.work
  mkdir -p $dir.work
  $kajo aot $aot $img -o $dir.work/c > $dir.work/aot.log 2>&1 || { cat $dir.work/aot.log; die "kajo aot failed" }
  libs=()
  for a in $archs; do
    (cd $dir.work/c && ls kajo_native_*.c | xargs -P $(sysctl -n hw.ncpu) -I{} $cc -target $a-apple-$osver$suffix $flags -c {} -o {}.$a.o) \
      || die "the generated C did not compile for $a"
    libtool -static -o $dir.work/lib-$a.a $dir.work/c/*.$a.o || die "libtool failed for $a"
    libs+=($dir.work/lib-$a.a)
  done
  if (( ${#libs} == 1 )); then mv $libs[1] $dir.work/libkajo_native.a; else lipo -create $libs -output $dir.work/libkajo_native.a || die "lipo failed"; fi
  mkdir -p $dir
  mv $dir.work/libkajo_native.a $lib
  shasum -a 256 $lib | cut -d' ' -f1 > $dir/stamp.new
  mv $dir/stamp.new $dir/stamp
  rm -rf $dir.work
fi
mkdir -p ${link:h}
[[ $(readlink $link 2>/dev/null) == $lib ]] || ln -sf $lib $link
# Xcode does not see a library named by a linker flag change: when the
# library is not the one the product was linked with, the product's
# executable goes, so the link runs again.
if [[ ! -f ${link:h}/linked || $(cat ${link:h}/linked) != $(cat $dir/stamp) ]]; then
  [[ -n ${TARGET_BUILD_DIR:-} && -n ${EXECUTABLE_PATH:-} ]] && rm -f "$TARGET_BUILD_DIR/$EXECUTABLE_PATH"
  cp $dir/stamp ${link:h}/linked
fi
# The libraries no platform links any more (an earlier image, kajo or
# clang) go: each would be about 4 MB for good.
keep=()
for l in $cache/native/*/libkajo_native.a(N@); do keep+=(${$(readlink $l):h:t}); done
removed=0
for d in $cache/native/*(N/); do
  k=${d:t}
  [[ ${#k} == 24 && $k != *[^0-9a-f]* && ${keep[(Ie)$k]} == 0 ]] || continue
  rm -rf $d
  removed=$(( removed + 1 ))
done
(( removed == 0 )) || print "native module: libraries of earlier builds removed: $removed"
